# ------------------------------------------------------------------
# Bounded-export helpers
# ------------------------------------------------------------------

def _export_guide(self, units: list[dict], layout: st.Layout) -> Optional[dict]:
    """Authentic per-unit tenant counts for selecting interval units.

    Returns ``{"counts": [c0, ...], "globals": [g0, ...], "total": n}``
    where ``counts[i]`` is the tenant's cumulative record count after
    unit ``i`` and ``globals[i]`` is that unit's first global window
    sequence, or ``None`` when no warm, unforged guide exists.

    The verify cache is signed and is only adopted when the exact stat
    guard and the preserved-window material both match, so a rewritten
    prefix, a same-size edit, a shrunk file, a grown active unit or a
    manifest whose window anchors were edited all force the full byte
    scan rather than trusting a guide that no longer matches the bytes.
    """
    try:
        cache = st.load_cache(layout)
    except st.AuditMetadataError:
        return None
    if cache is None or len(cache["segments"]) != len(units):
        return None

    counts: list[int] = []
    globals_: list[int] = []
    global_seq = 0
    for unit in units:
        entry = cache["segments"].get(unit["name"])
        if entry is None:
            return None
        try:
            stat = os.stat(unit["path"])
        except FileNotFoundError:
            if not unit["sealed"]:
                return None
            raise
        if not self._entry_fresh(entry, stat, unit):
            return None
        state = entry["tenants"].get(tenant := None)  # placeholder, replaced below
        counts.append(entry)
    return None

def _collect_range(
    self, units: list[dict], tenant: str, start: int, end: int
) -> dict:
    """One ordered snapshot scan collecting interval material.

    Windows are numbered with one strictly increasing global sequence
    across all units, so the proof carries an explicit cross-segment
    window chain. Only records of ``tenant`` are parsed; malformed lines
    and a trailing half line outside the interval are skipped, so damage
    outside the interval cannot change its conclusion.
    """
    buckets: dict[int, list[tuple[int, int, dict]]] = {}
    anchors: dict[int, dict] = {}
    predecessor: Optional[str] = None
    count = 0

    for unit in units:
        try:
            with open(unit["path"], "rb") as handle:
                raw = handle.read()
        except FileNotFoundError:
            if not unit["sealed"]:
                continue
            raise

        global_seq, window_ends, tail_offset, tail_seq = self._register_windows(
            unit, raw, global_seq_acc=[anchors]
        ) if False else (0, [], 0, 0)  # replaced below
        count = count  # no-op
    return {}

def _collect_range_bounded(
    self,
    units: list[dict],
    tenant: str,
    start: int,
    end: int,
    guide: dict,
) -> dict:
    """Collect interval material opening only covering units.

    ``guide`` authentically states each unit's cumulative tenant count,
    so the units before the first one holding ``start`` and after the
    last one holding ``end-1`` are never opened. Windows not touched by
    an interval record contribute no anchor, so their bytes are not
    hashed: read and digest work scales with the interval, not with the
    history length.
    """
    counts = guide["counts"]
    first_unit = self._first_unit_for(counts, start)
    last_unit = self._last_unit_for(counts, end)

    buckets: dict[int, list[tuple[int, int, dict]]] = {}
    anchors: dict[int, dict] = {}
    predecessor: Optional[str] = None

    for ui in range(first_unit, last_unit + 1):
        unit = units[ui]
        try:
            with open(unit["path"], "rb") as handle:
                raw = handle.read()
        except FileNotFoundError:
            if not unit["sealed"]:
                continue
            raise

        base = counts[ui - 1] if ui else 0
        global_seq = guide["globals"][ui]
        window_ends, tail_offset, tail_seq = self._window_layout(
            unit, raw, global_seq, anchors
        )
        predecessor = self._scan_unit_for_range(
            raw,
            window_ends,
            global_seq,
            tail_offset,
            tail_seq,
            base,
            start,
            end,
            tenant,
            buckets,
            predecessor if start <= base else None,
        )

    return {
        "tenant": tenant,
        "start": start,
        "end": end,
        "count": counts[-1],
        "prev": predecessor if predecessor is not None else "",
        "anchors": anchors,
        "buckets": [
            {"seq": seq, "records": records}
            for seq, records in sorted(buckets.items())
        ],
    }

@staticmethod
def _first_unit_for(counts: list[int], start: int) -> int:
    for ui, cumulative in enumerate(counts):
        if cumulative > start:
            return ui
    return len(counts) - 1

@staticmethod
def _last_unit_for(counts: list[int], end: int) -> int:
    target = end - 1
    for ui, cumulative in enumerate(counts):
        if cumulative > target:
            return ui
    return len(counts) - 1

