    if start == end:
        raise ValueError("range must be a non-empty interval")
    if start >= count or end > count:
        raise ValueError("range is out of bounds")

    return {
        "tenant": tenant,
        "start": start,
        "end": end,
        "count": count,
        "prev": predecessor if predecessor is not None else "",
        "anchors": anchors,
        "buckets": [
            {"seq": seq, "records": records}
