def _export_guide(
    self, units: list[dict], layout: st.Layout, tenant: str
) -> Optional[dict]:
    """Authentic per-unit tenant counts for selecting interval units.

    Returns ``{"counts": [c0, ...], "total": n}`` where ``counts[i]`` is
    the tenant's cumulative record count after unit ``i``, or ``None``
    when no warm, unforged guide exists.

    The verify cache is signed and a unit is adopted only when the exact
    stat guard and the preserved-window material both match, so a
    rewritten prefix, a same-size edit, a shrunk file, a grown active
    unit or a manifest whose window anchors were edited all force the
    full byte scan rather than trusting a guide that no longer matches
    the bytes.
    """
    try:
        cache = st.load_cache(layout)
    except st.AuditMetadataError:
        return None
    if cache is None or len(cache["segments"]) != len(units):
        return None

    counts: list[int] = []
    for unit in units:
        entry = cache["segments"].get(unit["name"])
        if entry is None:
            return None
        try:
            stat = os.stat(unit["path"])
        except FileNotFoundError:
            if not unit["sealed"]:
                return None
            raise
        if not self._entry_fresh(entry, stat, unit):
            return None
        state = entry["tenants"].get(tenant)
        counts.append(state[0] if state is not None else 0)
    return {"counts": counts, "total": counts[-1]}

